        for c in range(w):
            if grid[r][c] == 0 or visited[r][c]:
                continue
            color = grid[r][c]
            stack = [(r, c)]
            visited[r][c] = True
            cells = []

            while stack:
                x, y = stack.pop()
                cells.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < h and 0 <= ny < w and not visited[nx][ny] and grid[nx][ny] == color:
                        visited[nx][ny] = True
                        stack.append((nx, ny))

            min_r = min(x for x, _ in cells)
            max_r = max(x for x, _ in cells)
            min_c = min(y for _, y in cells)
            max_c = max(y for _, y in cells)

            blocks.append({
                "color": color,
                "r": min_r,
                "c": min_c,
                "r2": max_r,
                "c2": max_c,
            })

    n = len(blocks)
    if n <= 1:
        return [row[:] for row in grid]

    # Candidate edges: consecutive blocks in the same row or column.
    edges = []

    rows = {}
    cols = {}
    for i, b in enumerate(blocks):
        rows.setdefault(b["r"], []).append(i)
        cols.setdefault(b["c"], []).append(i)

